const src = $('查询待评分文章').item.json;
const raw = $json?.choices?.[0]?.message?.content ?? '';
let parsed = {};
try {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  parsed = JSON.parse(start >= 0 && end > start ? raw.slice(start, end + 1) : raw);
} catch (e) {
  return { json: { article_id: src.article_id, status: 'NEEDS_MANUAL', error: String(e) } };
}
return {
  json: {
    article_id: src.article_id,
    summary: parsed.summary ?? null,
    core_thesis: parsed.core_thesis ?? null,
    key_points: parsed.key_points ?? [],
    second_order: parsed.second_order ?? null,
    sentiment_score: parsed.sentiment_score ?? null,
    relevance_score: parsed.relevance_score ?? null,
    tags: parsed.tags ?? [],
    status: 'SCORED'
  }
};
